input.content:
:root {
  --bg: #070a12;
  --text: #eef2fa;
  --muted: #8d97ae;
  --panel: rgba(14, 19, 32, 0.74);
  --line: rgba(255, 255, 255, 0.08);
  --line-strong: rgba(255, 255, 255, 0.14);
  --accent: #ffb35c;
  --accent-hot: #ff6a3d;
  --danger: #ff8a72;
  --shadow: 0 24px 60px rgba(0, 0, 0, 0.45);
  --radius: 18px;
  --font: ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", Inter, Roboto, "Helvetica Neue", Arial, sans-serif;
}

* { box-sizing: border-box; }

html, body {
  height: 100%;
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  -webkit-font-smoothing: antialiased;
  overflow: hidden;
  overscroll-behavior: none;
}

body {
  touch-action: none;
  -webkit-tap-highlight-color: transparent;
}

button { font-family: inherit; }

#scene {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  outline: none;
  cursor: crosshair;
  touch-action: none;
}

#scene.is-orbiting { cursor: grabbing; }
#scene.is-erase { cursor: cell; }

.vignette {
  position: fixed;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(120% 90% at 50% 42%, transparent 38%, rgba(2, 4, 9, 0.62) 100%),
    linear-gradient(to bottom, rgba(4, 6, 12, 0.55), transparent 18%, transparent 78%, rgba(4, 6, 12, 0.5));
  z-index: 2;
}

/* ---------- top bar ---------- */

.topbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding: 16px 20px calc(16px + env(safe-area-inset-top));
  pointer-events: none;
}

.topbar > * { pointer-events: auto; }

.brand {
  display: flex;
  align-items: center;
  gap: 11px;
  min-width: 0;
}

.logo {
  width: 40px;
  height: 40px;
  flex: 0 0 auto;
  filter: drop-shadow(0 6px 14px rgba(210, 31, 43, 0.35));
}

.brand-text h1 {
  margin: 0;
  font-size: 14px;
  font-weight: 800;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  line-height: 1.2;
  white-space: nowrap;
}

.brand-text p {
  margin: 2px 0 0;
  font-size: 11px;
  letter-spacing: 0.02em;
  color: var(--muted);
  white-space: nowrap;
}

.head-actions {
  display: flex;
  align-items: center;
  gap: 7px;
}

.count-chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  height: 38px;
  padding: 0 14px;
  margin-right: 4px;
  border-radius: 999px;
  background: rgba(12, 17, 28, 0.72);
  border: 1px solid var(--line);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  color: #dbe2f1;
}

.count-chip #brickCount { font-weight: 700; color: #fff; }
.count-label { color: var(--muted); }

.count-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--accent-hot);
  box-shadow: 0 0 0 3px rgba(255, 106, 61, 0.15);
}

.icon-btn {
  -webkit-appearance: none;
  appearance: none;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  height: 38px;
  padding: 0 12px;
  border-radius: 11px;
  border: 1px solid var(--line);
  background: rgba(12, 17, 28, 0.72);
  color: #cdd5e6;
  font-size: 11.5px;
  font-weight: 600;
  letter-spacing: 0.01em;
  cursor: pointer;
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  transition: background 0.16s ease, border-color 0.16s ease, color 0.16s ease, transform 0.16s ease;
}

.icon-btn svg { width: 16px; height: 16px; flex: 0 0 auto; }

.icon-btn:hover {
  background: rgba(30, 39, 61, 0.85);
  border-color: var(--line-strong);
  color: #fff;
  transform: translateY(-1px);
}

.icon-btn:active { transform: translateY(0); }

.icon-btn[aria-pressed="false"] { color: #6e7890; }
.icon-btn[aria-pressed="false"] .wave { opacity: 0.15; }

/* ---------- control panel ---------- */

.panel {
  position: fixed;
  z-index: 20;
  left: 20px;
  top: 50%;
  transform: translateY(-50%);
  width: 272px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  max-height: calc(100dvh - 130px);
  overflow-y: auto;
  scrollbar-width: none;
}

.panel::-webkit-scrollbar { display: none; }

.group {
  padding: 14px;
  border-radius: var(--radius);
  border: 1px solid var(--line);
  background: var(--panel);
  backdrop-filter: blur(22px) saturate(140%);
  -webkit-backdrop-filter: blur(22px) saturate(140%);
  box-shadow: var(--shadow);
}

.group-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 11px;
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--muted);
}

.group-value {
  letter-spacing: 0.04em;
  font-size: 10.5px;
  color: #e8d8bd;
  font-weight: 700;
  text-transform: none;
}

/* sizes */

.sizes {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 7px;
}

.size-btn {
  -webkit-appearance: none;
  appearance: none;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
  min-height: 64px;
  padding: 9px 4px 7px;
  border-radius: 11px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  background: rgba(255, 255, 255, 0.035);
  color: #aab4c8;
  cursor: pointer;
  transition: border-color 0.15s ease, background 0.15s ease, color 0.15s ease, transform 0.15s ease;
}

.size-btn:hover {
  background: rgba(255, 255, 255, 0.07);
  color: #e9eefb;
  transform: translateY(-1px);
}

.size-btn.active {
  border-color: rgba(255, 179, 92, 0.7);
  background: linear-gradient(160deg, rgba(255, 179, 92, 0.2), rgba(255, 106, 61, 0.08));
  color: #ffd7a6;
  box-shadow: 0 0 0 1px rgba(255, 179, 92, 0.12) inset, 0 6px 18px rgba(255, 106, 61, 0.12);
}

.size-btn .dots {
  display: grid;
  grid-template-columns: repeat(var(--cols), 6px);
  grid-template-rows: repeat(var(--rows), 6px);
  gap: 2px;
  margin-bottom: auto;
}

.size-btn .dots i {
  display: block;
  border-radius: 50%;
  background: currentColor;
  opacity: 0.9;
  box-shadow: 0 1px 0 rgba(0, 0, 0, 0.35);
}

.size-btn .lbl {
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: inherit;
  opacity: 0.85;
}

/* colors */

.swatches {
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  gap: 7px;
}

.swatch {
  -webkit-appearance: none;
  appearance: none;
  position: relative;
  aspect-ratio: 1;
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, 0.16);
  padding: 0;
  cursor: pointer;
  box-shadow: inset 0 1px 1px rgba(255, 255, 255, 0.28), inset 0 -2px 4px rgba(0, 0, 0, 0.3);
  transition: transform 0.14s ease, outline-color 0.14s ease;
}

.swatch:hover { transform: scale(1.12); z-index: 2; }

.swatch.active {
  outline: 2px solid #fff;
  outline-offset: 2px;
  transform: scale(1.04);
  z-index: 3;
}

.swatch.active::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.3) inset;
}

/* tools */

.segmented {
  display: flex;
  gap: 3px;
  padding: 3px;
  border-radius: 12px;
  background: rgba(0, 0, 0, 0.28);
  border: 1px solid rgba(255, 255, 255, 0.05);
  margin-bottom: 8px;
}

.segmented button {
  -webkit-appearance: none;
  appearance: none;
  flex: 1;
  height: 34px;
  border: 0;
  border-radius: 9px;
  background: transparent;
  color: #97a2b9;
  font-size: 11.5px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease, box-shadow 0.15s ease;
}

.segmented button:hover { color: #e5ebf8; }

.segmented button.active {
  background: linear-gradient(180deg, #ffc574, #ff9f4a);
  color: #241304;
  box-shadow: 0 4px 14px rgba(255, 140, 60, 0.28), inset 0 1px 0 rgba(255, 255, 255, 0.45);
}

.segmented button[data-tool="erase"].active {
  background: linear-gradient(180deg, #ff9a86, #ff6f58);
  color: #260b06;
  box-shadow: 0 4px 14px rgba(255, 90, 70, 0.24), inset 0 1px 0 rgba(255, 255, 255, 0.4);
}

.row3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 7px;
}

.tool-btn {
  -webkit-appearance: none;
  appearance: none;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  padding: 8px 3px;
  border-radius: 10px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  background: rgba(255, 255, 255, 0.035);
  color: #b7c0d3;
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: 0.03em;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease;
}

.tool-btn svg { width: 15px; height: 15px; }

.tool-btn:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.07);
  border-color: var(--line-strong);
  color: #fff;
}

.tool-btn:disabled { opacity: 0.32; cursor: default; }

.clear-btn {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 32px;
  margin-top: 8px;
  border-radius: 9px;
  border: 1px solid rgba(255, 110, 90, 0.2);
  background: transparent;
  color: rgba(255, 138, 114, 0.85);
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.04em;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease;
}

.clear-btn:hover {
  background: rgba(255, 90, 70, 0.1);
  border-color: rgba(255, 110, 90, 0.4);
  color: #ffb4a2;
}

/* ---------- hint ---------- */

.hint {
  position: fixed;
  z-index: 15;
  left: 50%;
  bottom: calc(20px + env(safe-area-inset-bottom));
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 9px 16px;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: rgba(10, 14, 24, 0.66);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  font-size: 11.5px;
  color: #aab4c8;
  white-space: nowrap;
  pointer-events: none;
}

.hint-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 10px rgba(255, 179, 92, 0.9);
}

.hint .sep { color: #4f5a70; }

/* ---------- toast ---------- */

.toast {
  position: fixed;
  z-index: 60;
  left: 50%;
  bottom: calc(74px + env(safe-area-inset-bottom));
  transform: translate(-50%, 12px);
  padding: 10px 18px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(18, 25, 41, 0.92);
  color: #f1f5ff;
  font-size: 12.5px;
  font-weight: 600;
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.45);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s ease, transform 0.2s ease;
}

.toast.show { opacity: 1; transform: translate(-50%, 0); }

/* ---------- modal ---------- */

.modal {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: grid;
  place-items: center;
  padding: 20px;
  background: rgba(3, 5, 10, 0.66);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}

.modal[hidden] { display: none; }

.modal-card {
  position: relative;
  width: min(540px, 100%);
  max-height: min(86dvh, 720px);
  overflow-y: auto;
  padding: 30px 30px 26px;
  border-radius: 24px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: linear-gradient(170deg, #151d2f 0%, #0d1322 100%);
  box-shadow: 0 40px 100px rgba(0, 0, 0, 0.6);
  animation: card-in 0.22s cubic-bezier(0.2, 0.8, 0.3, 1);
}

@keyframes card-in {
  from { opacity: 0; transform: translateY(10px) scale(0.985); }
  to { opacity: 1; transform: none; }
}

.eyebrow {
  margin: 0 0 8px;
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--accent);
}

.modal-card h2 {
  margin: 0 0 22px;
  font-size: clamp(24px, 4vw, 30px);
  line-height: 1.15;
  letter-spacing: -0.02em;
  font-weight: 800;
}

.modal-close {
  position: absolute;
  top: 16px;
  right: 16px;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.04);
  color: #cdd5e6;
  font-size: 20px;
  line-height: 1;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease;
}

.modal-close:hover { background: rgba(255, 255, 255, 0.1); color: #fff; }

.steps { display: flex; flex-direction: column; gap: 15px; }

.step { display: flex; gap: 13px; align-items: flex-start; }

.step-num {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: 27px;
  height: 27px;
  border-radius: 9px;
  background: rgba(255, 179, 92, 0.12);
  border: 1px solid rgba(255, 179, 92, 0.28);
  color: #ffcf94;
  font-size: 12px;
  font-weight: 800;
}

.step strong { display: block; font-size: 13.5px; margin-bottom: 2px; }
.step p { margin: 0; font-size: 12.5px; line-height: 1.5; color: var(--muted); }

.shortcuts {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 9px 18px;
  margin: 24px 0 0;
  padding: 18px 0 0;
  border-top: 1px solid var(--line);
}

.shortcuts > div {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 11.5px;
  color: var(--muted);
}

.shortcuts span { margin-left: 4px; }

kbd {
  display: inline-grid;
  place-items: center;
  min-width: 22px;
  height: 22px;
  padding: 0 5px;
  border-radius: 6px;
  border: 1px solid rgba(255, 255, 255, 0.13);
  border-bottom-width: 2px;
  background: rgba(255, 255, 255, 0.05);
  color: #d6deee;
  font-family: var(--font);
  font-size: 10px;
  font-weight: 700;
}

.footnote {
  margin: 22px 0 0;
  font-size: 11px;
  line-height: 1.55;
  color: #6e7890;
}

.footnote strong { color: #aab4c8; }

/* ---------- responsive ---------- */

@media (max-width: 1180px) {
  .brand-text p { display: none; }
  .icon-btn .lbl { display: none; }
  .icon-btn { width: 38px; padding: 0; justify-content: center; }
  .count-chip { height: 36px; }
}

@media (max-width: 900px) {
  .topbar {
    padding: 12px 14px calc(12px + env(safe-area-inset-top));
    gap: 10px;
  }

  .logo { width: 34px; height: 34px; }
  .brand-text h1 { font-size: 12px; letter-spacing: 0.14em; }

  .count-chip { display: none; }
  .head-actions { gap: 5px; }
  .icon-btn { height: 36px; width: 36px; border-radius: 10px; }
  .icon-btn svg { width: 15px; height: 15px; }

  .panel {
    left: 0;
    right: 0;
    bottom: 0;
    top: auto;
    transform: none;
    width: auto;
    max-height: 54dvh;
    padding: 10px 12px calc(10px + env(safe-area-inset-bottom));
    gap: 8px;
    border-top: 1px solid var(--line);
    background: linear-gradient(to top, rgba(9, 13, 22, 0.96), rgba(9, 13, 22, 0.82));
    backdrop-filter: blur(22px);
    -webkit-backdrop-filter: blur(22px);
    overflow-y: auto;
  }

  .group {
    padding: 9px;
    border-radius: 14px;
    box-shadow: none;
    background: rgba(255, 255, 255, 0.025);
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
  }

  .group-head { display: none; }

  .sizes {
    display: flex;
    gap: 6px;
    overflow-x: auto;
    scrollbar-width: none;
    padding: 1px;
  }

  .sizes::-webkit-scrollbar { display: none; }

  .size-btn {
    flex: 0 0 auto;
    width: 58px;
    min-height: 54px;
    padding: 7px 4px 5px;
    gap: 4px;
  }

  .size-btn .lbl { font-size: 9px; }

  .swatches {
    display: flex;
    gap: 7px;
    overflow-x: auto;
    scrollbar-width: none;
    padding: 2px;
  }

  .swatches::-webkit-scrollbar { display: none; }

  .swatch {
    flex: 0 0 auto;
    width: 30px;
    height: 30px;
    aspect-ratio: auto;
    border-radius: 9px;
  }

  .group:nth-child(3) {
    display: grid;
    grid-template-columns: 1fr auto;
    grid-template-areas: "seg tools" "clear clear";
    gap: 7px;
    align-items: center;
  }

  .segmented { grid-area: seg; margin-bottom: 0; }
  .segmented button { height: 34px; font-size: 10.5px; }
  .row3 { grid-area: tools; display: flex; gap: 6px; }
  .tool-btn { width: 46px; padding: 6px 2px; font-size: 8px; }
  .tool-btn svg { width: 14px; height: 14px; }
  .clear-btn { grid-area: clear; margin-top: 0; height: 28px; }

  .hint { display: none; }

  .toast {
    top: calc(64px + env(safe-area-inset-top));
    bottom: auto;
    transform: translate(-50%, -8px);
    font-size: 12px;
  }

  .toast.show { transform: translate(-50%, 0); }

  .modal { padding: 14px; align-items: center; }
  .modal-card { padding: 24px 20px 20px; border-radius: 20px; max-height: 88dvh; }
  .shortcuts { grid-template-columns: 1fr; }
}

@media (max-width: 420px) {
  .brand-text h1 { font-size: 11px; }
  .icon-btn { width: 33px; height: 34px; }
  .head-actions { gap: 4px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    transition-duration: 0.001ms !important;
  }
}

import * as THREE from 'three';
import { RoundedBoxGeometry } from '../vendor/RoundedBoxGeometry.js';
import { mergeGeometries } from '../vendor/BufferGeometryUtils.js';

/* ------------------------------------------------------------------ *
 *  Constants
 * ------------------------------------------------------------------ */

const GRID = 24;            // baseplate is GRID x GRID studs
const H = 1.2;              // brick height in world units
const GAP = 0.045;          // hairline gap between neighbouring bricks
const STUD_R = 0.29;
const STUD_H = 0.16;
const MAX_LEVEL = 24;
const AUTO_KEY = 'brickstudio.autosave.v1';
const SLOT_KEY = 'brickstudio.slot.v1';
const SOUND_KEY = 'brickstudio.sound';

const COLORS = [
  { name: 'Cherry',      hex: '#d0212c' },
  { name: 'Tangerine',   hex: '#f2761d' },
  { name: 'Butter',      hex: '#f4c62a' },
  { name: 'Lime',        hex: '#a3c31a' },
  { name: 'Forest',      hex: '#2c8a49' },
  { name: 'Mint',        hex: '#7fd6b0' },
  { name: 'Sky',         hex: '#4bb2e6' },
  { name: 'Ocean',       hex: '#1566c9' },
  { name: 'Violet',      hex: '#7b4bd6' },
  { name: 'Magenta',     hex: '#df3f97' },
  { name: 'Pink',        hex: '#f6a3c1' },
  { name: 'Cream',       hex: '#f1ede2' },
  { name: 'Sand',        hex: '#e3cd9e' },
  { name: 'Brown',       hex: '#80502f' },
  { name: 'Slate',       hex: '#8b93a1' },
  { name: 'Charcoal',    hex: '#2a2d35' },
];

const SIZES = [
  { w: 1, d: 1 },
  { w: 2, d: 1 },
  { w: 4, d: 1 },
  { w: 2, d: 2 },
  { w: 2, d: 3 },
  { w: 4, d: 2 },
];

const clamp = (v, min, max) => Math.min(max, Math.max(min, v));
const damp = (current, target, lambda, dt) => current + (target - current) * (1 - Math.exp(-lambda * dt));

/* ------------------------------------------------------------------ *
 *  Renderer, scene, camera
