function refreshHighlight() {
  if (state.tool !== 'erase' || !state.hover || !state.hover.brick) {
    highlight.visible = false;
    return;
  }
  const b = state.hover.brick;
  highlight.position.set(centerX(b.x, b.w), b.level * H + H / 2, centerZ(b.z, b.d));
  highlight.scale.set(b.w + 0.06, H + 0.08, b.d + 0.06);
  highlight.visible = true;
}

function refreshPreview() {
  refreshGhost();
  refreshHighlight();
}

/* ------------------------------------------------------------------ *
 *  Interactions
 * ------------------------------------------------------------------ */

let audioCtx = null;

function ensureAudio() {
  if (!state.sound) return null;
  if (!audioCtx) {
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return null;
    audioCtx = new Ctx();
  }
  if (audioCtx.state === 'suspended') audioCtx.resume();
  return audioCtx;
}

function blip(freq, dur, type, gain, slide = 0, delay = 0) {
  const ctx = ensureAudio();
  if (!ctx) return;
  const t0 = ctx.currentTime + delay;
  const osc = ctx.createOscillator();
  const amp = ctx.createGain();
  osc.type = type;
  osc.frequency.setValueAtTime(freq, t0);
  osc.frequency.exponentialRampToValueAtTime(Math.max(40, freq + slide), t0 + dur);
  amp.gain.setValueAtTime(0.0001, t0);
  amp.gain.exponentialRampToValueAtTime(gain, t0 + 0.008);
  amp.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
  osc.connect(amp).connect(ctx.destination);
  osc.start(t0);
  osc.stop(t0 + dur + 0.02);
}

function soundPlace() {
  blip(520, 0.07, 'triangle', 0.07, 240);
  blip(980, 0.045, 'sine', 0.035, 90, 0.035);
}

function soundRemove() {
  blip(300, 0.09, 'triangle', 0.05, -110);
}

function soundDeny() {
  blip(180, 0.09, 'square', 0.025, -40);
}

function soundUi() {
  blip(720, 0.035, 'sine', 0.03, 80);
}

function pushHistory() {
  history.push(JSON.stringify(serialize()));
  if (history.length > 80) history.shift();
  future.length = 0;
  syncHistoryButtons();
}

function commitAndPlace(target) {
  if (!target) return;
  if (!target.valid) {
    if (target.brick) soundDeny();
    return;
  }
  pushHistory();
  addBrick(
    { x: target.x, z: target.z, level: target.level, w: target.w, d: target.d, color: state.color.hex },
    { animate: true },
  );
  soundPlace();
  afterChange();
}

function commitAndErase(brick) {
  if (!brick) return;
  pushHistory();
  removeBrick(brick);
  soundRemove();
  afterChange();
}

function afterChange() {
  refreshPreview();
  updateCount();
  queueAutosave();
}

function undo() {
  if (!history.length) return;
  future.push(JSON.stringify(serialize()));
  rebuild(JSON.parse(history.pop()));
  soundUi();
  syncHistoryButtons();
}

function redo() {
  if (!future.length) return;
  history.push(JSON.stringify(serialize()));
  rebuild(JSON.parse(future.pop()));
  soundUi();
  syncHistoryButtons();
}

function rebuild(bricks) {
  clearBricks();
  for (const data of bricks) addBrick(data, { animate: false });
  state.hover = null;
  refreshPreview();
  updateCount();
  queueAutosave();
}

function serialize() {
  return state.bricks.map(({ data }) => ({
    x: data.x,
    z: data.z,
    level: data.level,
    w: data.w,
    d: data.d,
    color: data.color,
  }));
}

/* ------------------------------------------------------------------ *
 *  Pointer + orbit controls
 * ------------------------------------------------------------------ */

const pointers = new Map();
let drag = null;
let pinch = null;
let downInfo = null;

function panBy(dx, dy) {
  const right = new THREE.Vector3().setFromMatrixColumn(camera.matrix, 0);
  const up = new THREE.Vector3().setFromMatrixColumn(camera.matrix, 1);
  const scale = orbit.tRadius * 0.00115;
  orbit.tTarget.addScaledVector(right, -dx * scale).addScaledVector(up, dy * scale);
  orbit.tTarget.x = clamp(orbit.tTarget.x, -12, 12);
  orbit.tTarget.z = clamp(orbit.tTarget.z, -12, 12);
  orbit.tTarget.y = clamp(orbit.tTarget.y, 0.2, 10);
}

function onPointerDown(e) {
  if (e.button !== undefined && e.button > 2) return;
  if (!e.isPrimary && e.pointerType === 'mouse') return;

  closeHelpIfOpen();

  canvas.setPointerCapture?.(e.pointerId);
  pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });

  if (pointers.size === 2) {
    const [a, b] = [...pointers.values()];
    pinch = { dist: Math.hypot(a.x - b.x, a.y - b.y), mid: { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 } };
    drag = null;
    downInfo = null;
    return;
  }

  if (pointers.size > 2) return;

  const isPan = e.pointerType === 'mouse' && (e.button === 1 || e.button === 2);
  drag = { mode: isPan ? 'pan' : 'orbit', lastX: e.clientX, lastY: e.clientY };
  downInfo = { x: e.clientX, y: e.clientY, time: performance.now(), button: e.button, type: e.pointerType };
  canvas.classList.add('is-orbiting');
}

function onPointerMove(e) {
  if (pointers.has(e.pointerId)) pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });

  if (pointers.size === 2 && pinch) {
    const [a, b] = [...pointers.values()];
    const dist = Math.hypot(a.x - b.x, a.y - b.y);
    const mid = { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 };
    if (pinch.dist > 0 && dist > 0) {
      orbit.tRadius = clamp(orbit.tRadius * (pinch.dist / dist), 10, 72);
    }
    panBy(mid.x - pinch.mid.x, mid.y - pinch.mid.y);
    pinch = { dist, mid };
    return;
  }

  if (drag) {
    const dx = e.clientX - drag.lastX;
    const dy = e.clientY - drag.lastY;
    drag.lastX = e.clientX;
    drag.lastY = e.clientY;

    if (downInfo) {
      const total = Math.hypot(e.clientX - downInfo.x, e.clientY - downInfo.y);
      if (total > 6) downInfo.moved = true;
    }

    if (drag.mode === 'orbit') {
      orbit.tTheta -= dx * 0.0062;
      orbit.tPhi = clamp(orbit.tPhi - dy * 0.0062, 0.2, 1.43);
    } else {
      panBy(dx, dy);
    }
    return;
  }

  if (e.pointerType === 'mouse' || e.pointerType === 'pen') {
    state.hover = targetFromClient(e.clientX, e.clientY);
    refreshPreview();
  }
}

function onPointerUp(e) {
  const wasTap =
    downInfo &&
    !downInfo.moved &&
    pointers.size === 1 &&
    performance.now() - downInfo.time < 800 &&
    (!downInfo.button || downInfo.button === 0) &&
    !pinch;

  pointers.delete(e.pointerId);

  if (pointers.size < 2) pinch = null;
  if (pointers.size === 0) {
    drag = null;
    canvas.classList.remove('is-orbiting');
  } else {
    drag = null;
  }

  if (wasTap) {
    if (state.tool === 'build') {
      commitAndPlace(targetFromClient(e.clientX, e.clientY));
      if (e.pointerType !== 'mouse') {
        state.hover = targetFromClient(e.clientX, e.clientY);
        refreshPreview();
      }
    } else {
      const target = targetFromClient(e.clientX, e.clientY);
      commitAndErase(target?.brick);
      state.hover = target;
      refreshPreview();
    }
  }

  downInfo = null;
}

function onPointerLeave(e) {
  if (e.pointerType === 'mouse' && !drag) {
    state.hover = null;
    refreshPreview();
  }
}

canvas.addEventListener('pointerdown', onPointerDown);
canvas.addEventListener('pointermove', onPointerMove);
canvas.addEventListener('pointerup', onPointerUp);
canvas.addEventListener('pointercancel', onPointerUp);
canvas.addEventListener('pointerleave', onPointerLeave);
canvas.addEventListener('contextmenu', (e) => e.preventDefault());
canvas.addEventListener(
  'wheel',
  (e) => {
    e.preventDefault();
    orbit.tRadius = clamp(orbit.tRadius * Math.exp(e.deltaY * 0.0011), 10, 72);
  },
  { passive: false },
);

/* ------------------------------------------------------------------ *
 *  Camera loop
 * ------------------------------------------------------------------ */

function updateCamera(dt) {
  orbit.theta = damp(orbit.theta, orbit.tTheta, 12, dt);
  orbit.phi = damp(orbit.phi, orbit.tPhi, 12, dt);
  orbit.radius = damp(orbit.radius, orbit.tRadius, 10, dt);
  orbit.target.x = damp(orbit.target.x, orbit.tTarget.x, 12, dt);
  orbit.target.y = damp(orbit.target.y, orbit.tTarget.y, 12, dt);
  orbit.target.z = damp(orbit.target.z, orbit.tTarget.z, 12, dt);

  const sinPhi = Math.sin(orbit.phi);
  camera.position.set(
    orbit.target.x + orbit.radius * sinPhi * Math.sin(orbit.theta),
    orbit.target.y + orbit.radius * Math.cos(orbit.phi),
    orbit.target.z + orbit.radius * sinPhi * Math.cos(orbit.theta),
  );
  camera.lookAt(orbit.target);
}

function resize() {
  const w = window.innerWidth;
  const h = window.innerHeight;
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(w, h, false);
  camera.aspect = w / h;
  camera.updateProjectionMatrix();
}
window.addEventListener('resize', resize);
window.addEventListener('orientationchange', () => setTimeout(resize, 120));

/* ------------------------------------------------------------------ *
 *  UI
 * ------------------------------------------------------------------ */

const ui = {
  sizes: document.getElementById('sizes'),
  swatches: document.getElementById('swatches'),
  sizeLabel: document.getElementById('sizeLabel'),
  colorLabel: document.getElementById('colorLabel'),
  brickCount: document.getElementById('brickCount'),
  countChip: document.getElementById('countChip'),
  toast: document.getElementById('toast'),
  hint: document.getElementById('hint'),
  undo: document.getElementById('undoBtn'),
  redo: document.getElementById('redoBtn'),
  sound: document.getElementById('soundBtn'),
  help: document.getElementById('helpModal'),
  helpBtn: document.getElementById('helpBtn'),
  helpClose: document.getElementById('helpClose'),
  toolButtons: [...document.querySelectorAll('[data-tool]')],
};

let toastTimer = 0;

function toast(message) {
  ui.toast.textContent = message;
  ui.toast.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => ui.toast.classList.remove('show'), 2200);
}

function updateCount() {
  const n = countBricks();
  ui.brickCount.textContent = n;
  ui.countChip.title = `${n} brick${n === 1 ? '' : 's'} on the baseplate`;
}

function syncHistoryButtons() {
  ui.undo.disabled = history.length === 0;
  ui.redo.disabled = future.length === 0;
}

function updateSizeLabel() {
  const { w, d } = currentSize();
  ui.sizeLabel.textContent = `${w}×${d}`;
}

function selectSize(index, quiet = false) {
  state.sizeIndex = index;
  [...ui.sizes.children].forEach((btn, i) => {
    const active = i === state.sizeIndex;
    btn.classList.toggle('active', active);
    btn.setAttribute('aria-pressed', String(active));
  });
  updateSizeLabel();
  refreshGhost();
  if (!quiet) soundUi();
}

function selectColor(color, quiet = false) {
  state.color = color;
  [...ui.swatches.children].forEach((btn) => {
    const active = btn.dataset.hex === color.hex;
    btn.classList.toggle('active', active);
    btn.setAttribute('aria-pressed', String(active));
  });
  ui.colorLabel.textContent = color.name;
  refreshGhost();
  if (!quiet) soundUi();
}

function setTool(tool, quiet = false) {
  state.tool = tool;
  ui.toolButtons.forEach((btn) => {
    const active = btn.dataset.tool === tool;
    btn.classList.toggle('active', active);
    btn.setAttribute('aria-pressed', String(active));
  });
  canvas.classList.toggle('is-erase', tool === 'erase');
  ui.hint.innerHTML =
    tool === 'build'
      ? '<span class="hint-dot" aria-hidden="true"></span> Drag to orbit <span class="sep">·</span> scroll to zoom <span class="sep">·</span> click to place'
      : '<span class="hint-dot" aria-hidden="true"></span> Click any brick to lift it off';
  refreshPreview();
  if (!quiet) soundUi();
}

function rotate() {
  state.rotated = !state.rotated;
  updateSizeLabel();
  refreshGhost();
  soundUi();
}

function openHelp() {
  ui.help.hidden = false;
  ui.helpClose.focus();
}

function closeHelp() {
  if (ui.help.hidden) return;
  ui.help.hidden = true;
  ui.helpBtn.focus();
}

function closeHelpIfOpen() {
  if (!ui.help.hidden) closeHelp();
}

/* ------------------------------------------------------------------ *
 *  Persistence
 * ------------------------------------------------------------------ */

let autosaveTimer = 0;

function queueAutosave() {
  clearTimeout(autosaveTimer);
  autosaveTimer = setTimeout(() => {
    try {
      localStorage.setItem(AUTO_KEY, JSON.stringify({ v: 1, bricks: serialize() }));
    } catch {
      /* storage may be unavailable */
    }
  }, 350);
}

function readStore(key) {
  try {
    const raw = localStorage.getItem(key);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed?.bricks) ? parsed.bricks : null;
  } catch {
    return null;
  }
}

function loadBuild(bricks, message) {
  if (!bricks || !bricks.length) {
    toast(message || 'That save is empty');
    return;
  }
  clearBricks();
  for (const data of bricks) addBrick(data, { animate: false });
  history.length = 0;
  future.length = 0;
  syncHistoryButtons();
  state.hover = null;
  refreshPreview();
  updateCount();
  queueAutosave();
  if (message) toast(message);
}

function saveBuild() {
  try {
    localStorage.setItem(SLOT_KEY, JSON.stringify({ v: 1, bricks: serialize() }));
    toast('Build saved to this browser');
    soundUi();
  } catch {
    toast('Could not save in this browser');
  }
}

function exportPng() {
  renderer.render(scene, camera);
  try {
    const link = document.createElement('a');
    link.download = `brick-studio-${new Date().toISOString().slice(0, 10)}.png`;
    link.href = renderer.domElement.toDataURL('image/png');
    link.click();
    toast('PNG snapshot exported');
    soundUi();
  } catch {
    toast('Export is not available here');
  }
}

/* ------------------------------------------------------------------ *
 *  Demo build (first visit)
 * ------------------------------------------------------------------ */

function buildDemo() {
  const walls = [];
  const roof = [];
  const extra = [];
  const TAN = '#e3cd9e';
  const CREAM = '#f1ede2';
  const RED = '#c8232c';
  const DARK_RED = '#a61b25';
  const PATH = '#8b93a1';
  const PATH_ALT = '#b9c0cc';
  const BROWN = '#80502f';
  const GREEN = '#2c8a49';
  const LIME = '#7fae22';

  const wall = (x, z, level, w, d, color = TAN) => walls.push({ x, z, level, w, d, color });

  // Front wall (door gap in the middle)
  for (const level of [0, 1]) {
    wall(8, 8, level, 2, 1);
    wall(10, 8, level, 1, 1);
    wall(13, 8, level, 1, 1);
    wall(14, 8, level, 2, 1);
  }
  wall(8, 8, 2, 4, 1, CREAM);
  wall(12, 8, 2, 4, 1, CREAM);

  // Back wall
  for (const level of [0, 1, 2]) {
    wall(8, 15, level, 4, 1, level === 2 ? CREAM : TAN);
    wall(12, 15, level, 4, 1, level === 2 ? CREAM : TAN);
  }

  // Side walls with little windows at level 1
  for (const x of [8, 15]) {
    wall(x, 9, 0, 1, 4);
    wall(x, 13, 0, 1, 2);
    wall(x, 9, 1, 1, 2);
    wall(x, 13, 1, 1, 2);
    wall(x, 9, 2, 1, 4, CREAM);
    wall(x, 13, 2, 1, 2, CREAM);
  }

  // Stepped roof, one stud of overhang all the way round
  const rows = (level, x0, x1, z0, z1, color, colorAlt) => {
    for (let z = z0; z < z1; z += 2) {
      const d = Math.min(2, z1 - z);
      let x = x0;
      const rowColor = ((z - z0) / 2) % 2 === 0 ? color : colorAlt;
      while (x < x1) {
        const w = Math.min(4, x1 - x);
        roof.push({ x, z, level, w, d, color: rowColor });
        x += w;
      }
    }
  };

  rows(3, 7, 17, 7, 17, RED, DARK_RED);
  rows(4, 8, 16, 8, 16, DARK_RED, RED);
  rows(5, 9, 15, 9, 15, RED, DARK_RED);
  rows(6, 10, 14, 10, 14, DARK_RED, RED);
  roof.push({ x: 11, z: 11, level: 7, w: 2, d: 2, color: RED });

  // Garden path leading to the door
  for (let z = 4; z <= 7; z++) {
    extra.push({ x: 11, z, level: 0, w: 2, d: 1, color: z % 2 === 0 ? PATH : PATH_ALT });
  }

  // Tree
  extra.push({ x: 18, z: 13, level: 0, w: 1, d: 1, color: BROWN });
  extra.push({ x: 18, z: 13, level: 1, w: 1, d: 1, color: BROWN });
  extra.push({ x: 17, z: 12, level: 2, w: 2, d: 2, color: GREEN });
  extra.push({ x: 19, z: 15, level: 0, w: 1, d: 1, color: LIME });

  // A few flowers / bushes
  extra.push({ x: 6, z: 6, level: 0, w: 1, d: 1, color: '#df3f97' });
  extra.push({ x: 7, z: 17, level: 0, w: 1, d: 1, color: '#f4c62a' });
  extra.push({ x: 16, z: 18, level: 0, w: 1, d: 1, color: GREEN });
  extra.push({ x: 18, z: 8, level: 0, w: 1, d: 1, color: '#4bb2e6' });

  for (const data of [...walls, ...roof, ...extra]) addBrick(data, { animate: false });
  updateCount();
  queueAutosave();
}

