  // Front facade, door and two little windows (level 2)
  for (const level of [0, 1]) {
    wall(8, 8, level, 2, 1);
    wall(10, 8, level, 1, 1);
    wall(11, 8, level, 2, 1, DOOR);
    wall(13, 8, level, 1, 1);
    wall(14, 8, level, 2, 1);
  }
  wall(8, 8, 2, 1, 1, CREAM);
  wall(9, 8, 2, 1, 1, GLASS);
  wall(10, 8, 2, 1, 1, CREAM);
  wall(11, 8, 2, 2, 1, CREAM);
  wall(13, 8, 2, 1, 1, CREAM);
  wall(14, 8, 2, 1, 1, GLASS);
  wall(15, 8, 2, 1, 1, CREAM);
  wall(8, 8, 3, 4, 1, CREAM);
  wall(12, 8, 3, 4, 1, CREAM);

  // Back wall
  for (const level of [0, 1]) {
    wall(8, 15, level, 4, 1, TAN);
    wall(12, 15, level, 4, 1, TAN);
  }
  wall(8, 15, 2, 2, 1, CREAM);
  wall(10, 15, 2, 1, 1, CREAM);
  wall(11, 15, 2, 2, 1, GLASS);
  wall(13, 15, 2, 1, 1, CREAM);
  wall(14, 15, 2, 2, 1, CREAM);
  wall(8, 15, 3, 4, 1, CREAM);
  wall(12, 15, 3, 4, 1, CREAM);

  // Side walls with a window at level 2
  for (const x of [8, 15]) {
    for (const level of [0, 1]) {
      wall(x, 9, level, 1, 4);
      wall(x, 13, level, 1, 2);
