function buildDemo() {
  const walls = [];
  const roof = [];
  const extra = [];
  const TAN = '#e3cd9e';
  const CREAM = '#f1ede2';
  const CHARCOAL = '#333844';
  const SLATE = '#8b93a1';
  const PATH = '#8b93a1';
  const PATH_ALT = '#b9c0cc';
  const BROWN = '#80502f';
  const DOOR = '#1566c9';
  const GLASS = '#4bb2e6';
  const GREEN = '#2c8a49';
  const LIME = '#7fae22';

  const wall = (x, z, level, w, d, color = TAN) => walls.push({ x, z, level, w, d, color });

  // Front wall with a blue door and two wide windows
  for (const level of [0, 1]) {
    wall(8, 8, level, 2, 1);
    wall(10, 8, level, 1, 1);
    wall(11, 8, level, 2, 1, DOOR);
    wall(13, 8, level, 1, 1);
    wall(14, 8, level, 2, 1);
  }
  wall(8, 8, 2, 2, 1, GLASS);
  wall(10, 8, 2, 4, 1, CREAM);
  wall(14, 8, 2, 2, 1, GLASS);
  wall(8, 8, 3, 4, 1, CREAM);
  wall(12, 8, 3, 4, 1, CREAM);

  // Back wall
  for (const level of [0, 1]) {
    wall(8, 15, level, 4, 1, TAN);
    wall(12, 15, level, 4, 1, TAN);
  }
  wall(8, 15, 2, 1, 1, CREAM);
  wall(9, 15, 2, 3, 1, GLASS);
  wall(12, 15, 2, 3, 1, GLASS);
  wall(15, 15, 2, 1, 1, CREAM);
  wall(8, 15, 3, 4, 1, CREAM);
  wall(12, 15, 3, 4, 1, CREAM);

  // Side walls, with a long window at level 2
  for (const x of [8, 15]) {
    for (const level of [0, 1]) {
      wall(x, 9, level, 1, 4);
      wall(x, 13, level, 1, 2);
    }
    wall(x, 9, 2, 1, 1, CREAM);
    wall(x, 10, 2, 1, 2, GLASS);
    wall(x, 12, 2, 1, 2, CREAM);
    wall(x, 14, 2, 1, 1, CREAM);
    wall(x, 9, 3, 1, 4, CREAM);
    wall(x, 13, 3, 1, 2, CREAM);
  }

  // Flat roof slab with a one-stud overhang
  const rows = (level, x0, x1, z0, z1, color, colorAlt) => {
    for (let z = z0; z < z1; z += 2) {
      const d = Math.min(2, z1 - z);
      let x = x0;
      const rowColor = ((z - z0) / 2) % 2 === 0 ? color : colorAlt;
      while (x < x1) {
        const w = Math.min(4, x1 - x);
        roof.push({ x, z, level, w, d, color: rowColor });
        x += w;
      }
    }
  };
  rows(4, 7, 17, 7, 17, CHARCOAL, '#2b303a');

  // Parapet around the roof terrace
  const parapet = (x, z, w, d) => roof.push({ x, z, level: 5, w, d, color: CREAM });
  parapet(7, 7, 4, 1);
  parapet(11, 7, 4, 1);
  parapet(15, 7, 2, 1);
  parapet(7, 16, 4, 1);
  parapet(11, 16, 4, 1);
  parapet(15, 16, 2, 1);
  for (const x of [7, 16]) {
    parapet(x, 8, 1, 4);
    parapet(x, 12, 1, 4);
  }

  // Awning above the door
  extra.push({ x: 11, z: 7, level: 3, w: 2, d: 1, color: CHARCOAL });

  // Rooftop terrace: planter, tree and flowers
  extra.push({ x: 8, z: 8, level: 5, w: 2, d: 2, color: BROWN });
  extra.push({ x: 8, z: 8, level: 6, w: 1, d: 1, color: '#df3f97' });
  extra.push({ x: 9, z: 9, level: 6, w: 1, d: 1, color: LIME });
  extra.push({ x: 14, z: 9, level: 5, w: 1, d: 1, color: BROWN });
  extra.push({ x: 13, z: 8, level: 6, w: 2, d: 2, color: GREEN });
  extra.push({ x: 11, z: 9, level: 5, w: 1, d: 1, color: '#f4c62a' });
  extra.push({ x: 12, z: 12, level: 5, w: 2, d: 1, color: SLATE });

  // Garden path leading to the door
  extra.push({ x: 11, z: 7, level: 0, w: 2, d: 1, color: PATH });
  for (let z = 3; z <= 6; z++) {
    extra.push({ x: 11, z, level: 0, w: 2, d: 1, color: z % 2 === 0 ? PATH_ALT : PATH });
  }

  // Tree
  extra.push({ x: 18, z: 13, level: 0, w: 1, d: 1, color: BROWN });
  extra.push({ x: 18, z: 13, level: 1, w: 1, d: 1, color: BROWN });
  extra.push({ x: 17, z: 12, level: 2, w: 2, d: 2, color: GREEN });
  extra.push({ x: 19, z: 15, level: 0, w: 1, d: 1, color: LIME });

  // A few flowers / bushes
  extra.push({ x: 6, z: 6, level: 0, w: 1, d: 1, color: '#df3f97' });
  extra.push({ x: 7, z: 17, level: 0, w: 1, d: 1, color: '#f4c62a' });
  extra.push({ x: 16, z: 18, level: 0, w: 1, d: 1, color: GREEN });
  extra.push({ x: 18, z: 8, level: 0, w: 1, d: 1, color: GLASS });

  for (const data of [...walls, ...roof, ...extra]) addBrick(data, { animate: false });
  updateCount();
  queueAutosave();
}

