```js
function buildDemo() {
  const bands = [ ... ];
  const bricks = [];
  const zRows = [9, 11];
  for (let level=0; level<10; level++) {
    const row = [];
    for (let x=0;x<GRID;x++) {
      const dx = x + 0.5 - 12;
      const dy = level + 0.5;
      const dist = Math.hypot(dx, dy);
      if (dist >= 4 && dist < 10) {
        const band = Math.min(bands.length-1, Math.floor(10 - dist));
        row.push({x, band});
      }
    }
    // group contiguous
    let i=0;
    while (i<row.length) {
      let j=i;
      while (j+1<row.length && row[j+1].x === row[j].x+1 && row[j+1].band === row[i].band) j++;
      // run row[i..j]
      let start = row[i].x, end = row[j].x; // inclusive
      let cursor=start;
      while (cursor<=end) {
        const w = Math.min(4, end-cursor+1);
        for (const z of zRows) bricks.push({x:cursor,z,level,w,d:2,color:bands[row[i].band]});
        cursor += w;
      }
      i=j+1;
    }
  }
  for (const b of bricks) addBrick(b,{animate:false});
}
```
