import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core/index.mjs';

const base = 'http://localhost:3002/';
const out = '/home/runner/work/PlayGround/PlayGround/screenshots';
const logs = [];
const errors = [];

const browser = await chromium.launch({
  headless: false,
  executablePath: '/home/runner/.cache/ms-playwright/chromium-1248/chrome-linux64/chrome',
  args: ['--enable-gpu', '--ignore-gpu-blocklist', '--use-angle=swiftshader'],
});

async function track(page, label) {
  page.on('console', (m) => {
    if (m.type() === 'error') logs.push(`${label} console.error: ${m.text()}`);
  });
  page.on('pageerror', (e) => errors.push(`${label} pageerror: ${e.message}`));
  page.on('requestfailed', (r) => errors.push(`${label} requestfailed: ${r.url()} ${r.failure()?.errorText}`));
}

// ---------- desktop ----------
const desktop = await browser.newContext({ viewport: { width: 1200, height: 800 }, deviceScaleFactor: 1 });
const page = await desktop.newPage();
await track(page, 'desktop');
await page.goto(base + '?fresh=17', { waitUntil: 'networkidle' });
await page.waitForFunction(() => window.__brickStudio && window.__brickStudio.state.bricks.length > 0);
await page.waitForTimeout(900);

const desktopCount = await page.evaluate(() => window.__brickStudio.serialize().length);
const ghost = await page.evaluate(() => {
  const s = window.__brickStudio;
  const g = s.scene.children.find((o) => o.isMesh && o.material?.transparent && o.renderOrder === 4);
  return { count: s.scene.children.length, opacity: g?.material.opacity, visible: g?.visible };
});

// Hover over an empty plate area for the ghost.
await page.mouse.move(250, 640);
await page.waitForTimeout(350);
const hoverState = await page.evaluate(() => {
  const s = window.__brickStudio;
  const g = s.scene.children.find((o) => o.isMesh && o.material?.transparent && o.renderOrder === 4);
  return { hover: !!s.state.hover, ghostVisible: g?.visible, opacity: g?.material.opacity };
});
await page.screenshot({ path: `${out}/final-desktop.png` });

// Placement via mouse click on empty plate.
const beforePlace = await page.evaluate(() => window.__brickStudio.serialize().length);
await page.mouse.click(250, 640);
await page.waitForTimeout(250);
const afterPlace = await page.evaluate(() => window.__brickStudio.serialize().length);

// Undo it again to preserve the demo.
await page.keyboard.press('Control+z');
await page.waitForTimeout(150);
const afterUndo = await page.evaluate(() => window.__brickStudio.serialize().length);

// ---------- mobile / touch ----------
const mobile = await browser.newContext({
  viewport: { width: 390, height: 844 },
  deviceScaleFactor: 2,
  isMobile: true,
  hasTouch: true,
});
const mpage = await mobile.newPage();
await track(mpage, 'mobile');
await mpage.goto(base + '?fresh=18', { waitUntil: 'networkidle' });
await mpage.waitForFunction(() => window.__brickStudio && window.__brickStudio.state.bricks.length > 0);
await mpage.waitForTimeout(900);
await mpage.screenshot({ path: `${out}/final-mobile.png` });

const touchPlaceBefore = await mpage.evaluate(() => window.__brickStudio.serialize().length);
// Tap empty baseplate area (visible around lower-left of the plate).
await mpage.touchscreen.tap(70, 480);
await mpage.waitForTimeout(350);
const touchPlaceAfter = await mpage.evaluate(() => window.__brickStudio.serialize().length);

// Switch to erase and tap a known brick.
const brickPt = await mpage.evaluate(() => {
  const s = window.__brickStudio;
  const b = s.state.bricks[Math.floor(s.state.bricks.length / 2)];
  const p = b.mesh.position.clone();
  p.y += 0.5;
  p.project(s.camera);
  const r = document.getElementById('scene').getBoundingClientRect();
  return {
    x: r.left + ((p.x + 1) / 2) * r.width,
    y: r.top + ((-p.y + 1) / 2) * r.height,
  };
});
await mpage.getByRole('button', { name: /erase/i }).click();
await mpage.waitForTimeout(200);
await mpage.touchscreen.tap(brickPt.x, brickPt.y);
await mpage.waitForTimeout(400);
const touchEraseAfter = await mpage.evaluate(() => window.__brickStudio.serialize().length);

// Ghost should not linger after touch tap.
const ghostAfterTap = await mpage.evaluate(() => {
  const s = window.__brickStudio;
  const g = s.scene.children.find((o) => o.isMesh && o.material?.transparent && o.renderOrder === 4);
  return { hover: s.state.hover, ghostVisible: g?.visible };
});

// Return to build mode for a clean screenshot.
await mpage.getByRole('button', { name: /^build$/i }).click();
await mpage.waitForTimeout(200);

// One-finger drag should orbit, not place.
const beforeDrag = await mpage.evaluate(() => window.__brickStudio.serialize().length);
await mpage.touchscreen.tap(200, 300); // reset hover baseline (this places one; undo below)
await mpage.keyboard.press('Control+z');
await mpage.waitForTimeout(100);
const beforeDrag2 = await mpage.evaluate(() => window.__brickStudio.serialize().length);
await mpage.mouse.move(200, 300);
await mpage.mouse.down();
await mpage.mouse.move(255, 320, { steps: 8 });
await mpage.mouse.up();
await mpage.waitForTimeout(300);
const afterDrag = await mpage.evaluate(() => window.__brickStudio.serialize().length);

console.log(JSON.stringify({
  desktopCount,
  ghost,
  hoverState,
  beforePlace,
  afterPlace,
  afterUndo,
  touchPlaceBefore,
  touchPlaceAfter,
  touchEraseAfter,
  ghostAfterTap,
  beforeDrag,
  beforeDrag2,
  afterDrag,
  logs,
  errors,
}, null, 2));

await browser.close();

