import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core/index.mjs';
const browser = await chromium.launch({ headless: false, executablePath: '/home/runner/.cache/ms-playwright/chromium-1248/chrome-linux64/chrome', args: ['--enable-gpu','--ignore-gpu-blocklist','--use-angle=swiftshader'] });

async function probe(ctxOpts, label) {
  const ctx = await browser.newContext(ctxOpts);
  const p = await ctx.newPage();
  await p.goto('http://localhost:3002/?fresh=99', { waitUntil: 'networkidle' });
  await p.waitForFunction(() => window.__brickStudio && window.__brickStudio.state.bricks.length > 0);
  await p.waitForTimeout(1500);
  const pts = await p.evaluate(() => {
    const s = window.__brickStudio;
    const canvas = document.getElementById('scene');
    const r = canvas.getBoundingClientRect();
    const out = [];
    for (const [x, z] of [[-9,9],[-9,6],[-6,9],[-8,4],[-4,9],[9,9],[9,6],[6,9],[8,4],[4,9],[-9,-6],[-6,-9]]) {
      const v = s.camera.position.clone();
      v.set(x, 0, z);
      v.project(s.camera);
      const sx = r.left + ((v.x + 1) / 2) * r.width;
      const sy = r.top + ((-v.y + 1) / 2) * r.height;
      const t = s.targetFromClient(sx, sy);
      out.push({ x, z, sx: Math.round(sx), sy: Math.round(sy), hit: t && { valid: t.valid, level: t.level, brick: !!t.brick, w: t.w } });
    }
    return { rect: { w: r.width, h: r.height, top: r.top }, pts: out };
  });
  console.log(label, JSON.stringify(pts));
  await ctx.close();
}

await probe({ viewport: { width: 1200, height: 800 } }, 'desktop');
await probe({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true }, 'mobile');
await browser.close();

