/* ------------------------------------------------------------------ *
 *  Interactions
 * ------------------------------------------------------------------ */

let audioCtx = null;

function ensureAudio() {
  if (!state.sound) return null;
  if (!audioCtx) {
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return null;
    audioCtx = new Ctx();
  }
  if (audioCtx.state === 'suspended') audioCtx.resume();
  return audioCtx;
}

function blip(freq, dur, type, gain, slide = 0, delay = 0) {
  const ctx = ensureAudio();
  if (!ctx) return;
  const t0 = ctx.currentTime + delay;
  const osc = ctx.createOscillator();
  const amp = ctx.createGain();
  osc.type = type;
  osc.frequency.setValueAtTime(freq, t0);
  osc.frequency.exponentialRampToValueAtTime(Math.max(40, freq + slide), t0 + dur);
  amp.gain.setValueAtTime(0.0001, t0);
  amp.gain.exponentialRampToValueAtTime(gain, t0 + 0.008);
  amp.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
  osc.connect(amp).connect(ctx.destination);
  osc.start(t0);
  osc.stop(t0 + dur + 0.02);
}

function soundPlace() {
  blip(520, 0.07, 'triangle', 0.07, 240);
  blip(980, 0.045, 'sine', 0.035, 90, 0.035);
}

function soundRemove() {
  blip(300, 0.09, 'triangle', 0.05, -110);
}

function soundDeny() {
  blip(180, 0.09, 'square', 0.025, -40);
}

function soundUi() {
  blip(720, 0.035, 'sine', 0.03, 80);
}

function pushHistory() {
  history.push(JSON.stringify(serialize()));
  if (history.length > 80) history.shift();
  future.length = 0;
  syncHistoryButtons();
}

function commitAndPlace(target) {
  if (!target) return;
  if (!target.valid) {
    if (target.brick) soundDeny();
    return;
  }
  pushHistory();
  addBrick(
    { x: target.x, z: target.z, level: target.level, w: target.w, d: target.d, color: state.color.hex },
    { animate: true },
  );
  soundPlace();
  state.hover = null;
  afterChange();
}

function commitAndErase(brick) {
  if (!brick) return;
  pushHistory();
  removeBrick(brick);
  soundRemove();
  state.hover = null;
  afterChange();
}

function afterChange() {
  refreshPreview();
  updateCount();
  queueAutosave();
}

function undo() {
  if (!history.length) return;
  future.push(JSON.stringify(serialize()));
  rebuild(JSON.parse(history.pop()));
  soundUi();
  syncHistoryButtons();
}

function redo() {
  if (!future.length) return;
  history.push(JSON.stringify(serialize()));
  rebuild(JSON.parse(future.pop()));
  soundUi();
  syncHistoryButtons();
}

function rebuild(bricks) {
  clearBricks();
  for (const data of bricks) addBrick(data, { animate: false });
  state.hover = null;
  refreshPreview();
  updateCount();
  queueAutosave();
}

function serialize() {
  return state.bricks.map(({ data }) => ({
    x: data.x,
    z: data.z,
    level: data.level,
    w: data.w,
    d: data.d,

  if (e.key === 'Escape') {
    closeHelp();
    return;
  }
  if (ui.help.hidden === false) return;

  if (mod && e.key.toLowerCase() === 'z') {
    e.preventDefault();
    if (e.shiftKey) redo();
    else undo();
    return;
  }
  if (mod && e.key.toLowerCase() === 'y') {
    e.preventDefault();
    redo();
    return;
  }
  if (mod || e.altKey) return;

  switch (e.key.toLowerCase()) {
    case 'b':
      setTool('build');
      break;
    case 'e':
      setTool('erase');
      break;
    case 'r':
      rotate();
      break;
    case 'f':
      document.getElementById('resetBtn').click();
      break;
    case 'm':
      ui.sound.click();
      break;
    case 'h':
    case '?':
      openHelp();
      break;
    default: {
      const n = Number(e.key);
      if (n >= 1 && n <= SIZES.length) selectSize(n - 1);
    }
  }
});

window.addEventListener('pagehide', () => {
  try {
    localStorage.setItem(AUTO_KEY, JSON.stringify({ v: 1, bricks: serialize() }));
  } catch {
    /* ignore */
  }
});

/* ------------------------------------------------------------------ *
 *  Boot
 * ------------------------------------------------------------------ */

resize();
selectSize(state.sizeIndex, true);
selectColor(state.color, true);

