await d.locator('#helpBtn').click();
const helpOpen = await d.locator('#helpModal').isVisible();
await d.keyboard.press('Escape');
const helpClosed = !(await d.locator('#helpModal').isVisible());
const canvasBox = await d.locator('#scene').boundingBox();

